import type { OrderEvent } from './contract';
import type { Database, Tx } from './support/db';

export interface Outbox {
  commit(work: (tx: Tx) => OrderEvent[]): void;
  dispatch(publish: (event: OrderEvent) => Promise<void>): Promise<number>;
  pending(): number;
}

const TABLE = 'outbox';

export function createOutbox(db: Database): Outbox {
  return {
    commit(work: (tx: Tx) => OrderEvent[]): void {
      db.transaction((tx) => {
        const events = work(tx);
        // 关键就是这一行的位置：事件的写入在业务写入的同一个事务回调里。
        // 挪到 transaction 外面，就退回成了「先写库再写 outbox」的两步问题
        for (const event of events) {
          tx.insert(TABLE, {
            id: event.id,
            type: event.type,
            payload: event.payload,
            delivered: false,
          });
        }
      });
    },

    async dispatch(publish: (event: OrderEvent) => Promise<void>): Promise<number> {
      const rows = db.rows(TABLE).filter((row) => row.delivered === false);
      let sent = 0;

      for (const row of rows) {
        const event: OrderEvent = {
          id: String(row.id),
          type: String(row.type),
          payload: row.payload as Record<string, unknown>,
        };

        try {
          // 先发送、成功了再标记。反过来的话，
          // 发送失败的事件已经被标成已投递，永远不会重试——静默丢失
          await publish(event);
        } catch (error) {
          // 保持顺序：中断整批，剩下的留到下一轮。
          // 跳过继续发会让同一个订单的事件倒序送达
          break;
        }

        db.transaction((tx) => {
          tx.update(TABLE, (candidate) => candidate.id === row.id, { delivered: true });
        });
        sent += 1;
      }

      return sent;
    },

    pending(): number {
      return db.rows(TABLE).filter((row) => row.delivered === false).length;
    },
  };
}

goal.en:
Message queues only guarantee at-least-once: the same event will be delivered twice.
Decrementing stock twice is real money lost.

Implement `createOrderProcessor(options)` in `src/processor.ts`:

- `process(event)`: run the middleware chain from stage 2;
- idempotency: a repeated `event.id` returns the previous result without running middleware again;
- retries: retry a failing event up to `maxAttempts - 1` times;
- dead letters: events that still fail land in a dead-letter queue readable via `deadLetters()`, without affecting later events;
- emit `order.processed` / `order.deadLettered` through `count()` from `@lab/metrics`.

The idempotency key has to engage before the side effect. Compensating afterwards is a much harder job, and it rarely cleans up everything.

