// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface Outbox {
//   commit(work: (tx: Tx) => OrderEvent[]): void;
//   dispatch(publish: (event: OrderEvent) => Promise<void>): Promise<number>;
//   pending(): number;
// }

const TABLE = 'outbox';
export function createOutbox(db) {
    return {
        commit(work) {
            db.transaction((tx) => {
                const events = work(tx);
                // 关键就是这一行的位置：事件的写入在业务写入的同一个事务回调里。
                // 挪到 transaction 外面，就退回成了「先写库再写 outbox」的两步问题
                for (const event of events) {
                    tx.insert(TABLE, {
                        id: event.id,
                        type: event.type,
                        payload: event.payload,
                        delivered: false,
                    });
                }
            });
        },
        async dispatch(publish) {
            const rows = db.rows(TABLE).filter((row) => row.delivered === false);
            let sent = 0;
            for (const row of rows) {
                const event = {
                    id: String(row.id),
                    type: String(row.type),
                    payload: row.payload,
                };
                try {
                    // 先发送、成功了再标记。反过来的话，
                    // 发送失败的事件已经被标成已投递，永远不会重试——静默丢失
                    await publish(event);
                }
                catch (error) {
                    // 保持顺序：中断整批，剩下的留到下一轮。
                    // 跳过继续发会让同一个订单的事件倒序送达
                    break;
                }
                db.transaction((tx) => {
                    tx.update(TABLE, (candidate) => candidate.id === row.id, { delivered: true });
                });
                sent += 1;
            }
            return sent;
        },
        pending() {
            return db.rows(TABLE).filter((row) => row.delivered === false).length;
        },
    };
}

