// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface ProcessorOptions {
//   middlewares: Middleware[];
//   maxAttempts?: number;
// }
//
// export interface ProcessOutcome {
//   ok: boolean;
//   deduplicated: boolean;
//   result?: unknown;
//   error?: string;
//   attempts: number;
// }
//
// export interface OrderProcessor {
//   process(event: OrderEvent): Promise<ProcessOutcome>;
//   deadLetters(): OrderEvent[];
// }

import { count } from '@lab/metrics';
import { compose } from './compose';
export function createOrderProcessor(options) {
    const run = compose(options.middlewares);
    const maxAttempts = Math.max(1, options.maxAttempts ?? 1);
    const processed = new Map();
    const dead = [];
    return {
        async process(event) {
            // 幂等检查必须在任何副作用之前
            if (processed.has(event.id)) {
                return {
                    ok: true,
                    deduplicated: true,
                    result: processed.get(event.id),
                    attempts: 0,
                };
            }
            let lastError;
            for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
                const ctx = { event, state: {} };
                try {
                    await run(ctx);
                    processed.set(event.id, ctx.result);
                    count('order.processed');
                    return { ok: true, deduplicated: false, result: ctx.result, attempts: attempt };
                }
                catch (error) {
                    lastError = error;
                }
            }
            dead.push(event);
            count('order.deadLettered');
            return {
                ok: false,
                deduplicated: false,
                error: lastError.message,
                attempts: maxAttempts,
            };
        },
        deadLetters() {
            return [...dead];
        },
    };
}

