// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export type Reducer = (
//   state: Record<string, unknown>,
//   event: OrderEvent
// ) => Record<string, unknown>;
//
// export interface Projection {
//   catchUp(events: OrderEvent[]): number;
//   checkpoint(): number;
//   state(): Record<string, unknown>;
//   reset(): void;
// }

export function createProjection(reduce) {
    let current = {};
    let position = 0;
    return {
        catchUp(events) {
            // 幂等就来自这一行：第二次追赶时 slice 是空的，什么都不会重复应用
            const pending = events.slice(position);
            for (const event of pending) {
                // 先应用、后推进 checkpoint。反过来的话，中间崩溃会让
                // 这个事件永远丢失——checkpoint 已经越过它了
                current = reduce(current, event);
                position += 1;
            }
            return pending.length;
        },
        checkpoint() {
            return position;
        },
        state() {
            // 交出副本：读模型是给很多地方查的，返回内部对象
            // 意味着任何一个调用方都能改坏它
            return { ...current };
        },
        reset() {
            // 读模型是派生数据，出错了的修复手段就是清空重建，
            // 所以这不是可选功能
            current = {};
            position = 0;
        },
    };
}

