  /** 全局配额的键，多个实例用同一个 */
  key: string;
  /** 每次向中心存储批发多少 */
  leaseSize: number;
  /** 批发失败后隔多久才再问一次，默认 100ms */
  retryAfterMs?: number;
}

export interface LeasedLimiter {
  allow(): boolean;
  /** 本地还剩多少批发来的额度 */
  localBalance(): number;
}

