export type Freshness = 'live' | 'stale' | 'fallback';

export interface DegradeResult {
  value: unknown;
  freshness: Freshness;
}

export interface DegradeOptions {
  /** 多久之内算新鲜 */
  ttlMs: number;
  /** 下游失败时，多久之内的旧值还能拿来用 */
  staleWhileErrorMs: number;
  /** 下游失败之后隔多久才再试一次 */
  retryAfterMs: number;
  /** 连旧值都没有时返回什么 */
  fallback(key: string): unknown;
}

export interface Degrader {
  /** 任何情况下都不抛异常 */
