// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface PipelineStats {
//   completed: number;
//   failed: number;
//   cacheHits: number;
// }
//
// export interface Pipeline {
//   run(urls: string[]): Promise<PageResult[]>;
//   stats(): PipelineStats;
